import React from 'react';

export type LocalIconProps = Omit<React.SVGProps<SVGSVGElement>, 'ref'> & {
    size?: string | number;
    title?: string;
};

type IconNode = {
    tag: string;
    attr: Record<string, string | number>;
    child?: IconNode[];
};

const renderNode = (node: IconNode, key: number): React.ReactNode =>
    React.createElement(
        node.tag,
        { key, ...node.attr },
        ...(node.child || []).map((child, index) => renderNode(child, index)),
    );

const createIcon = (displayName: string, data: IconNode): React.FC<LocalIconProps> => {
    const Icon: React.FC<LocalIconProps> = ({ size, title, children, width, height, ...props }) => (
        <svg
            {...data.attr}
            {...props}
            width={width ?? size ?? '1em'}
            height={height ?? size ?? '1em'}
            xmlns="http://www.w3.org/2000/svg"
        >
            {title ? <title>{title}</title> : null}
            {(data.child || []).map((child, index) => renderNode(child, index))}
            {children}
        </svg>
    );
    Icon.displayName = displayName;
    return Icon;
};

